import 'dart:convert';
import 'dart:io';

import 'package:dau_shared/dau_shared.dart';
import 'package:test/test.dart';

/// Vectors generated by Node, an independent regex engine, so a disagreement
/// between runtimes would show up here (see config/identity-vectors.json).
Map<String, Object?> _vectors() {
  final file = File('../../config/identity-vectors.json');
  return jsonDecode(file.readAsStringSync()) as Map<String, Object?>;
}

void main() {
  group('normaliseAlias', () {
    test('matches the shared vectors', () {
      final aliases = (_vectors()['aliases']! as List)
          .cast<Map<String, Object?>>();
      expect(aliases, isNotEmpty);
      for (final vector in aliases) {
        expect(
          normaliseAlias(vector['input']! as String),
          vector['normalised'],
          reason: 'input: ${vector['input']}',
        );
      }
    });

    test('ignores case, spacing, emoji and punctuation', () {
      for (final alias in ['R e i s y', 'Reisy🏈', 'REISY', 'r.e.i.s.y']) {
        expect(normaliseAlias(alias), 'reisy', reason: alias);
      }
    });

    test('keeps accents, so an accented alias is a different alias', () {
      expect(normaliseAlias('Réisy'), 'réisy');
      expect(normaliseAlias('Réisy'), isNot(normaliseAlias('Reisy')));
    });

    test(
      'yields a valid database key for any alias with a letter or digit',
      () {
        for (final alias in ['Tipper #1', '老虎', 'a.b/c', r'$ign[0]']) {
          final key = normaliseAlias(alias);
          expect(isValidRtdbKey(key), isTrue, reason: '$alias -> $key');
        }
      },
    );
  });

  group('isValidAlias', () {
    test('accepts ordinary aliases', () {
      for (final alias in ['Reisy', 'Big Fan', '老虎', 'Team 9']) {
        expect(isValidAlias(alias), isTrue, reason: alias);
      }
    });

    test('rejects blank aliases and aliases that are only symbols', () {
      for (final alias in ['', '   ', '😀😀', '!!!']) {
        expect(isValidAlias(alias), isFalse, reason: '"$alias"');
      }
    });

    test('allows exactly $maxAliasLength characters and no more', () {
      expect(isValidAlias('x' * maxAliasLength), isTrue);
      expect(isValidAlias('x' * (maxAliasLength + 1)), isFalse);
    });

    test('counts characters, not UTF-16 units', () {
      expect(isValidAlias('é${'🏈' * (maxAliasLength - 1)}'), isTrue);
      expect(isValidAlias('é${'🏈' * maxAliasLength}'), isFalse);
    });
  });

  group('normaliseEmail', () {
    test('matches the shared vectors', () {
      final emails = (_vectors()['emails']! as List)
          .cast<Map<String, Object?>>();
      for (final vector in emails) {
        expect(
          normaliseEmail(vector['input']! as String),
          vector['normalised'],
          reason: 'input: ${vector['input']}',
        );
      }
    });
  });
}
